{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  const E = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (cands !== null || ballots.length) E('candidates must be declared once, before any ballot')
    if (t.length < 2) E('expected candidates <name>...')
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) E(`invalid candidate name ${name}`)
      if (seen.has(name)) E(`candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = seen
  } else if (t[0] === 'ballot') {
    if (cands === null) E('candidates must be declared once, before any ballot')
    if (t.length < 3) E('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) E('count must be a positive integer')
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.has(name)) E(`unknown candidate ${name}`)
      if (seen.has(name)) E(`candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else {
    E(`unknown directive ${t[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b.count, 0)
const continuing = new Set(cands)
const history = []
const out = []
let nrounds = 0
let result = 'no winner'
for (;;) {
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  nrounds++
  history.push(counts)
  const order = [...counts].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  out.push(`round ${nrounds}: ${order.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
  if (active === 0) break
  const win = order.find(([, v]) => v * 2 > active)
  if (win) {
    result = `winner ${win[0]}`
    break
  }
  const min = Math.min(...counts.values())
  let set = [...counts].filter(([, v]) => v === min).map(([c]) => c)
  for (;;) {
    if (set.length === 1) break
    const r = history.find((h) => new Set(set.map((c) => h.get(c))).size > 1)
    if (!r) break
    const m = Math.min(...set.map((c) => r.get(c)))
    set = set.filter((c) => r.get(c) === m)
  }
  const elim = set.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
process.stdout.write((mode === 'tally' ? `rounds ${nrounds}\n${result}` : out.join('\n')) + '\n')
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write CLI and run tests"}

